'use strict';

// MODULES //

var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

var RE_VAR_DECLARATION = /\b(?:var|let|const) +([a-zA-Z_$][a-zA-Z0-9_$]*)/g;


// MAIN //

/**
* Rule for enforcing that variables are not redeclared within an examples section.
*
* @param {Context} context - lint context
* @returns {Object} validators
*/
function main( context ) {
	/**
	* Checks an examples section for variable redeclarations.
	*
	* @private
	* @param {Object} section - examples section
	*/
	function noRedeclare( section ) {
		var examples;
		var declared;
		var match;
		var i;

		declared = {};
		examples = section.examples;
		for ( i = 0; i < examples.length; i++ ) {
			RE_VAR_DECLARATION.lastIndex = 0;
			match = RE_VAR_DECLARATION.exec( examples[ i ].code );
			while ( match ) {
				if ( hasOwnProp( declared, match[ 1 ] ) ) {
					context.report( format( '%s is already defined', match[ 1 ] ), section );
				} else {
					declared[ match[ 1 ] ] = true;
				}
				match = RE_VAR_DECLARATION.exec( examples[ i ].code );
			}
		}
	}

	return {
		'examples': noRedeclare
	};
}


// EXPORTS //

module.exports = main;
